-- =====================================================================
-- GlucoCare — PostgreSQL / Supabase schema
--
-- This is the only schema the application uses. It is the direct translation of the
-- original MySQL schema, kept deliberately close to it so the PHP stays unchanged:
--   * ENUM columns become varchar + CHECK (same allowed values, same defaults)
--   * TINYINT(1) flags stay smallint 0/1, so (int) casts and !empty() keep working
--   * timestamps are plain timestamp (no zone) because the app stores local Kampala times
--   * auto-increment becomes GENERATED BY DEFAULT AS IDENTITY (explicit seed ids allowed)
--
-- Safe to re-run: every statement is IF NOT EXISTS / ON CONFLICT DO NOTHING.
-- =====================================================================

-- A hospital or clinic network. Every account belongs to exactly one organisation.
CREATE TABLE IF NOT EXISTS organisations (
    org_id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        varchar(120) NOT NULL,
    short_name  varchar(40) NOT NULL,
    is_active   smallint NOT NULL DEFAULT 1,
    created_at  timestamp NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS users (
    user_id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username              varchar(50) NOT NULL UNIQUE,
    password_hash         varchar(255) NOT NULL,
    role                  varchar(20) NOT NULL CHECK (role IN ('patient','clinician','admin','receptionist')),
    org_id                integer NOT NULL DEFAULT 1,
    totp_secret           varchar(64) NULL,
    totp_enabled          smallint NOT NULL DEFAULT 0,
    email                 varchar(100) NOT NULL UNIQUE,
    is_active             smallint NOT NULL DEFAULT 1,
    must_change_password  smallint NOT NULL DEFAULT 0,
    last_login_at         timestamp NULL,
    created_at            timestamp NOT NULL DEFAULT now()
);

-- Roles are constrained to a known set. Front-desk (receptionist) accounts were added
-- after the first release, so the constraint is replaced instead of only being widened
-- in the CREATE above (an existing database keeps its original constraint otherwise).
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK (role IN ('patient','clinician','admin','receptionist'));

-- Clinician profiles are created ONLY by hospital administrators.
CREATE TABLE IF NOT EXISTS clinicians (
    clinician_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         integer NOT NULL UNIQUE REFERENCES users(user_id) ON DELETE CASCADE,
    full_name       varchar(100) NOT NULL,
    specialization  varchar(100) NOT NULL,
    license_no      varchar(50) NOT NULL UNIQUE
);

-- Front-desk profiles. Same shape as clinicians: the login lives in users, the name here.
CREATE TABLE IF NOT EXISTS receptionists (
    receptionist_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          integer NOT NULL UNIQUE REFERENCES users(user_id) ON DELETE CASCADE,
    full_name        varchar(100) NOT NULL,
    desk             varchar(40) NULL
);

-- Clinical departments a patient can be referred to when no single doctor is named.
CREATE TABLE IF NOT EXISTS departments (
    department_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id         integer NOT NULL DEFAULT 1 REFERENCES organisations(org_id) ON DELETE CASCADE,
    name           varchar(80) NOT NULL,
    code           varchar(10) NOT NULL,
    is_active      smallint NOT NULL DEFAULT 1
);

-- clinician_id = the ONE doctor allowed to see this patient (set by an administrator).
CREATE TABLE IF NOT EXISTS patients (
    patient_id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         integer NOT NULL UNIQUE REFERENCES users(user_id) ON DELETE CASCADE,
    clinician_id    integer NULL REFERENCES clinicians(clinician_id) ON DELETE SET NULL,
    full_name       varchar(100) NOT NULL,
    date_of_birth   date NOT NULL,
    gender          varchar(10) NOT NULL CHECK (gender IN ('male','female','other')),
    phone           varchar(20) NOT NULL,
    allergies       varchar(255) NULL,
    preferred_unit  varchar(10) NOT NULL DEFAULT 'mg/dL' CHECK (preferred_unit IN ('mg/dL','mmol/L')),
    assigned_at     timestamp NULL
);

-- Per-patient target ranges (ADA defaults; clinicians can override).
CREATE TABLE IF NOT EXISTS patient_thresholds (
    threshold_id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id                integer NOT NULL UNIQUE REFERENCES patients(patient_id) ON DELETE CASCADE,
    target_fasting_min        numeric(5,2) NOT NULL DEFAULT 80.00,
    target_fasting_max        numeric(5,2) NOT NULL DEFAULT 130.00,
    target_postprandial_max   numeric(5,2) NOT NULL DEFAULT 180.00,
    hypo_threshold            numeric(5,2) NOT NULL DEFAULT 70.00,
    severe_hypo_threshold     numeric(5,2) NOT NULL DEFAULT 54.00,
    critical_high_threshold   numeric(5,2) NOT NULL DEFAULT 300.00,
    updated_at                timestamp NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS glucose_readings (
    reading_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id    integer NOT NULL REFERENCES patients(patient_id) ON DELETE CASCADE,
    glucose_value numeric(5,1) NOT NULL,
    entered_unit  varchar(10) NOT NULL DEFAULT 'mg/dL' CHECK (entered_unit IN ('mg/dL','mmol/L')),
    meal_context  varchar(20) NOT NULL CHECK (meal_context IN ('fasting','pre_meal','post_meal','bedtime','nocturnal')),
    symptoms      varchar(255) NULL,
    was_confirmed smallint NOT NULL DEFAULT 0,
    was_edited    smallint NOT NULL DEFAULT 0,
    edited_at     timestamp NULL,
    logged_at     timestamp NOT NULL,
    created_at    timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_patient_logged ON glucose_readings (patient_id, logged_at);

-- Alerts generated by the rule engine. A clinician sees only alerts of THEIR assigned patients.
CREATE TABLE IF NOT EXISTS clinical_alerts (
    alert_id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reading_id           integer NULL REFERENCES glucose_readings(reading_id) ON DELETE SET NULL,
    patient_id           integer NOT NULL REFERENCES patients(patient_id) ON DELETE CASCADE,
    clinician_id         integer NULL REFERENCES clinicians(clinician_id) ON DELETE SET NULL,
    alert_type           varchar(40) NOT NULL,
    risk_level           varchar(10) NOT NULL CHECK (risk_level IN ('low','moderate','high','critical')),
    data_confidence      varchar(10) NOT NULL CHECK (data_confidence IN ('high','low')),
    adherence_pct        numeric(5,1) NOT NULL DEFAULT 0,
    alert_message        text NOT NULL,
    status               varchar(10) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','reviewed','resolved')),
    clinician_note       varchar(255) NULL,
    created_at           timestamp NOT NULL DEFAULT now(),
    reviewed_at          timestamp NULL,
    resolved_at          timestamp NULL,
    digest_sent_at       timestamp NULL,
    digest_attempts      smallint NOT NULL DEFAULT 0,
    digest_error         varchar(255) NULL,
    patient_notified_at  timestamp NULL
);
CREATE INDEX IF NOT EXISTS idx_alert_patient ON clinical_alerts (patient_id, status, alert_type);

-- Vitals recorded by clinical staff. A prescription cannot be issued without recent vitals.
CREATE TABLE IF NOT EXISTS vitals (
    vital_id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id          integer NOT NULL REFERENCES patients(patient_id) ON DELETE CASCADE,
    recorded_by_user_id integer NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    systolic_bp         integer NOT NULL,
    diastolic_bp        integer NOT NULL,
    heart_rate          integer NOT NULL,
    weight_kg           numeric(5,1) NULL,
    temperature_c       numeric(3,1) NULL,
    notes               varchar(255) NULL,
    recorded_at         timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_vitals_patient ON vitals (patient_id, recorded_at);

CREATE TABLE IF NOT EXISTS prescriptions (
    prescription_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id       integer NOT NULL REFERENCES patients(patient_id) ON DELETE CASCADE,
    clinician_id     integer NOT NULL REFERENCES clinicians(clinician_id) ON DELETE CASCADE,
    vital_id         integer NULL REFERENCES vitals(vital_id) ON DELETE SET NULL,
    medication_name  varchar(100) NOT NULL,
    dosage           varchar(50) NOT NULL,
    frequency        varchar(50) NOT NULL,
    start_date       date NOT NULL,
    end_date         date NULL,
    status           varchar(15) NOT NULL DEFAULT 'active' CHECK (status IN ('active','completed','discontinued')),
    created_at       timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_rx_patient ON prescriptions (patient_id, status);

-- A referral IS NOT a diagnosis: it records that a patient was sent on to a doctor or a
-- department, with the reason given at the desk. Either a doctor or a department is named.
CREATE TABLE IF NOT EXISTS referrals (
    referral_id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id         integer NOT NULL REFERENCES patients(patient_id) ON DELETE CASCADE,
    referred_by_user_id integer NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    clinician_id        integer NULL REFERENCES clinicians(clinician_id) ON DELETE SET NULL,
    department_id       integer NULL REFERENCES departments(department_id) ON DELETE SET NULL,
    urgency             varchar(10) NOT NULL DEFAULT 'routine' CHECK (urgency IN ('routine','urgent','emergency')),
    reason              varchar(255) NOT NULL,
    status              varchar(15) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','completed','cancelled')),
    outcome_note        varchar(255) NULL,
    created_at          timestamp NOT NULL DEFAULT now(),
    updated_at          timestamp NULL,
    CHECK (clinician_id IS NOT NULL OR department_id IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_referral_patient ON referrals (patient_id, status);
CREATE INDEX IF NOT EXISTS idx_referral_clinician ON referrals (clinician_id, status);

-- Ground truth for the simulated datasets (used only by admin/evaluation.php).
CREATE TABLE IF NOT EXISTS sim_ground_truth (
    truth_id       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id     integer NOT NULL REFERENCES patients(patient_id) ON DELETE CASCADE,
    window_index   smallint NOT NULL,
    window_start   timestamp NOT NULL,
    window_end     timestamp NOT NULL,
    is_positive    smallint NOT NULL,
    severe_events  integer NOT NULL DEFAULT 0,
    note           varchar(40) NOT NULL DEFAULT ''
);

-- Small key/value store for job bookkeeping (last scan, last digest, last backup).
CREATE TABLE IF NOT EXISTS app_settings (
    setting_key    varchar(64) PRIMARY KEY,
    setting_value  text NULL,
    updated_at     timestamp NOT NULL DEFAULT now()
);

-- Single-use, hashed, time-limited password reset tokens.
CREATE TABLE IF NOT EXISTS password_resets (
    reset_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     integer NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    token_hash  char(64) NOT NULL,
    expires_at  timestamp NOT NULL,
    used_at     timestamp NULL,
    created_at  timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_reset_token ON password_resets (token_hash);

CREATE TABLE IF NOT EXISTS audit_logs (
    log_id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       integer NULL REFERENCES users(user_id) ON DELETE SET NULL,
    target_table  varchar(50) NOT NULL,
    action        varchar(50) NOT NULL,
    details       text NOT NULL,
    created_at    timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_audit_action ON audit_logs (target_table, action, created_at);

