-- Explicit ids above do not advance the identity sequences; move each one past its seed rows.
SELECT setval(pg_get_serial_sequence('organisations','org_id'), (SELECT MAX(org_id) FROM organisations));
SELECT setval(pg_get_serial_sequence('users','user_id'), (SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('clinicians','clinician_id'), (SELECT MAX(clinician_id) FROM clinicians));
SELECT setval(pg_get_serial_sequence('patients','patient_id'), (SELECT MAX(patient_id) FROM patients));
SELECT setval(pg_get_serial_sequence('receptionists','receptionist_id'), (SELECT MAX(receptionist_id) FROM receptionists));
SELECT setval(pg_get_serial_sequence('departments','department_id'), (SELECT MAX(department_id) FROM departments));
SELECT setval(pg_get_serial_sequence('patient_thresholds','threshold_id'), (SELECT MAX(threshold_id) FROM patient_thresholds));
SELECT setval(pg_get_serial_sequence('audit_logs','log_id'), (SELECT MAX(log_id) FROM audit_logs));
